//! The native oracle for the web-host Unicode candidate. Inputs are pinned;
//! expected outputs are generated by this toolchain, never by JavaScript.
use std::{collections::BTreeMap, fs, path::Path};
use serde_json::json;
use sha2::{Digest, Sha256};
use unicode_normalization::UnicodeNormalization;

fn text(hex: &str) -> String {
    hex.split_whitespace().map(|s| char::from_u32(u32::from_str_radix(s, 16).unwrap()).expect("Unicode scalar")).collect()
}

#[test]
fn host_nfc_canaries_match_native_tables_and_ascii_lowercase() {
    for (input, expected) in [("A\u{030A}", "\u{00C5}"), ("d\u{0323}\u{0307}", "\u{1E0D}\u{0307}"), ("\u{1E9B}\u{0323}", "\u{1E9B}\u{0323}"), ("\u{1100}\u{1161}", "\u{AC00}")] {
        assert_eq!(input.nfc().collect::<String>(), expected);
        assert_eq!(snapback4_core::words::fold(input), expected.to_lowercase());
    }
    for a in 0..128_u8 { for b in 0..128_u8 {
        let input = String::from_utf8(vec![a, b]).unwrap();
        assert_eq!(input.to_ascii_lowercase(), input.to_lowercase());
    } }
}

#[test]
fn unicode_fold_fixture() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/unicode-17.0.0");
    let sources: serde_json::Value = serde_json::from_str(&fs::read_to_string(fixtures.join("sources.json")).unwrap()).unwrap();
    for (name, source) in sources.as_object().unwrap() {
        assert_eq!(format!("{:x}", Sha256::digest(fs::read(fixtures.join(name)).unwrap())), source["sha256"].as_str().unwrap(), "{name}");
    }
    assert_eq!(unicode_normalization::UNICODE_VERSION, (17, 0, 0));
    let mut inputs = BTreeMap::new();
    let mut normalization_lines = 0;
    for (n, line) in fs::read_to_string(fixtures.join("NormalizationTest.txt")).unwrap().lines().enumerate() {
        let line = line.split('#').next().unwrap().trim();
        if line.is_empty() || line.starts_with('@') { continue; }
        let cols: Vec<_> = line.split(';').take(5).map(text).collect();
        assert_eq!(cols.len(), 5);
        for (i, input) in cols.iter().enumerate() {
            assert_eq!(input.nfc().collect::<String>(), cols[if i < 3 { 1 } else { 3 }], "NormalizationTest line {} column {}", n + 1, i + 1);
            inputs.entry(input.clone()).or_insert(format!("NormalizationTest:{}:{}", n + 1, i + 1));
        }
        normalization_lines += 1;
    }
    let mut mapped = 0;
    for line in fs::read_to_string(fixtures.join("UnicodeData.txt")).unwrap().lines() {
        let fields: Vec<_> = line.split(';').collect();
        if fields[13].is_empty() { continue; }
        let input = text(fields[0]);
        for (suffix, input) in [("", input.clone()), ("sigma-before", format!("AΣ{input}")), ("sigma-after", format!("{input}Σ"))] {
            inputs.entry(input).or_insert(format!("Lowercase_Mapping:{}:{suffix}", fields[0]));
        }
        mapped += 1;
    }
    let mut special = 0;
    for line in fs::read_to_string(fixtures.join("SpecialCasing.txt")).unwrap().lines() {
        let line = line.split('#').next().unwrap().trim();
        if line.is_empty() { continue; }
        let fields: Vec<_> = line.split(';').collect();
        inputs.entry(text(fields[0])).or_insert(format!("SpecialCasing:{}", fields[0]));
        special += 1;
    }
    // Context-dependent sigma, locale-independent I, astral letters, embedded
    // NUL, noncharacters, private use and unassigned scalars (never surrogates).
    for input in ["", "ASCII COFFEE 0123", "Σ", "ΟΣ", "ΟΣΑ", "AΣ\u{301}", "AΣ\u{301}A", "A'Σ", "AΣ'A", "AΣ'", "I İ ı i", "I\u{307}", "I\u{301}", "𐐀𐐨𐒰𐓘", "\0\u{feff}\u{10ffff}\u{fdd0}\u{e000}\u{0378}", "\r\n\t", "AΣ\u{200d}A"] {
        inputs.insert(input.to_owned(), "edge/context".into());
    }
    // Every ASCII scalar and pairs cover the fast path, including controls.
    for a in 0..128_u8 { for b in 0..128_u8 {
        inputs.insert(String::from_utf8(vec![a, b]).unwrap(), "ascii-pair".into());
    } }
    let cases: Vec<_> = inputs.into_iter().map(|(input, source)| {
        let nfc = input.nfc().collect::<String>();
        let fold = nfc.to_lowercase();
        assert_eq!(snapback4_core::words::fold(&input), fold, "{source}");
        let lower_refusal = snapback4_core::engine::validate::validate_arg(&snapback4_core::Schema::default(), &snapback4_core::ir::ArgType::Text { min: 0, max: 4000, format: None }, &snapback4_core::Value::String(input.clone()), "s").err().map(|e| e.refusal().code);
        json!({"lowerRefusal":lower_refusal, "source":source, "lower":input.to_lowercase(), "tokens":snapback4_core::words::tokens(&input), "input":input, "nfc":nfc, "fold":fold})
    }).collect();
    assert!(normalization_lines > 19000 && mapped > 1400 && special > 100);
    let output = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/unicode-fold.json");
    fs::create_dir_all(output.parent().unwrap()).unwrap();
    let fixture = json!({"normalizationUnicode":"17.0.0", "rustUnicode":format!("{}.{}.{}", char::UNICODE_VERSION.0, char::UNICODE_VERSION.1, char::UNICODE_VERSION.2), "sources":sources, "normalizationLines":normalization_lines, "lowercaseMappings":mapped, "specialCasingEntries":special, "cases":cases});
    fs::write(&output, serde_json::to_vec(&fixture).unwrap()).unwrap();
    println!("unicode fixture: {} cases; {normalization_lines} normalization lines (all 5 columns); {mapped} lowercase mappings; {special} special-casing entries; Rust Unicode {}; {}", fixture["cases"].as_array().unwrap().len(), fixture["rustUnicode"], output.display());
}
